css:
.absolute {
  position: absolute;
}
.relative {
  position: relative;
}
.left-0 {
  left: 0px;
}
.top-1\/2 {
  top: 50%;
}
.flex {
  display: flex;
}
.h-\[2em\] {
  height: 2em;
}
.w-\[2em\] {
  width: 2em;
}
.-translate-x-full {
  --tw-translate-x: -100%;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.-translate-y-1\/2 {
  --tw-translate-y: -50%;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y))
    rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y))
    scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y));
}
.cursor-pointer {
  cursor: pointer;
}
.appearance-none {
  -webkit-appearance: none;
  appearance: none;
}
.items-center {
  align-items: center;
}
.justify-center {
  justify-content: center;
}
.gap-\[1em\] {
  gap: 1em;
}
.rounded-\[0\.25em\] {
  border-radius: 0.25em;
}
.border-\[2px\] {
  border-width: 2px;
}
.border-\[\#FF91AF\] {
  --tw-border-opacity: 1;
  border-color: rgb(255 145 175 / var(--tw-border-opacity));
}
.text-\[1em\] {
  font-size: 1em;
}
.font-semibold {
  font-weight: 600;
}
.text-\[\#FF91AF\] {
  --tw-text-opacity: 1;
  color: rgb(255 145 175 / var(--tw-text-opacity));
}
.duration-500 {
  transition-duration: 500ms;
}
.ease-out {
  transition-timing-function: cubic-bezier(0, 0, 0.2, 1);
}
.\[stroke-dasharray\:1000\] {
  stroke-dasharray: 1000;
}
.\[stroke-dashoffset\:1000\] {
  stroke-dashoffset: 1000;
}
.\[user-select\:none\] {
  -webkit-user-select: none;
  user-select: none;
}
.peer:checked ~ .peer-checked\:\[stroke-dashoffset\:0\] {
  stroke-dashoffset: 0;
}
